import type { CSSProperties } from 'react';

/**
 * Small transparent WebP icons, generated by scripts/generate_ui_icons.py.
 * CSS mask retains currentColor behavior in light/dark themes.
 * Decorative only: interactive controls retain their accessible text labels.
 */
const knownIcons = new Set(['arrow', 'up', 'down', 'external', 'pin', 'game', 'code', 'layers', 'mail', 'phone', 'clock', 'sparkle', 'menu']);
export function Icon({ name, size = 24, style }: { name: string; size?: number; style?: CSSProperties }) {
  const icon = knownIcons.has(name) ? name : 'arrow';
  return <span
    className="ui-webp-icon"
    aria-hidden="true"
    style={{
      width: size,
      height: size,
      WebkitMaskImage: `url("/icons/${icon}.webp")`,
      maskImage: `url("/icons/${icon}.webp")`,
      ...style
    }}
  />;
}
